node --input-type=module -e '
import { persist, logWrite } from "./src/store.js";
import { readFileSync } from "node:fs";

const r1 = persist({ id: "ord-1", total: 12 });
if (!r1.ok || r1.id !== "ord-1") throw new Error("persist return mismatch");
const r2 = persist({ id: "ord-2", total: 30 });
const logged = logWrite({ ts: "2026-09-01T00:00:00.000Z", action: "manual", id: "probe" });
if (logged !== JSON.stringify({ ts: "2026-09-01T00:00:00.000Z", action: "manual", id: "probe" })) {
  throw new Error("logWrite did not return JSON");
}
try {
  persist({});
  throw new Error("missing id should throw");
} catch (err) {
  if (err.message !== "order.id required") throw err;
}
const orders = JSON.parse(readFileSync("data/orders.json", "utf8"));
if (!orders["ord-1"] || orders["ord-1"].total !== 12) throw new Error("ord-1 missing");
if (!orders["ord-2"] || orders["ord-2"].total !== 30) throw new Error("ord-2 missing");
const lines = readFileSync("data/writes.jsonl", "utf8").trim().split("\n");
if (lines.length < 3) throw new Error("expected at least 3 log lines");
for (const line of lines) JSON.parse(line);
console.log(JSON.stringify({ persist: r1, orders, writeLines: lines.length }, null, 2));
'
